package net.civeira.phylax.feature.observe.observedslo.infrastructure.repository;

import java.util.Iterator;
import java.util.List;
import java.util.function.BiFunction;

import net.civeira.phylax.common.algorithms.Slider;
import net.civeira.phylax.feature.observe.observedslo.domain.ObservedSlo;
import net.civeira.phylax.feature.observe.observedslo.domain.gateway.ObservedSloCursor;
import net.civeira.phylax.feature.observe.observedslo.domain.gateway.ObservedSloFilter;

class ObservedSloSlider extends Slider<ObservedSlo> {

  /**
   * @autogenerated SlideGenerator
   */
  private final ObservedSloCursor cursor;

  /**
   * @autogenerated SlideGenerator
   */
  private final ObservedSloFilter filter;

  /**
   * @autogenerated SlideGenerator
   */
  private final BiFunction<ObservedSloFilter, ObservedSloCursor, Iterator<ObservedSlo>> gateway;

  /**
   * @autogenerated SlideGenerator
   * @param multi
   * @param limit
   * @param gateway
   * @param filter
   * @param cursor
   */
  ObservedSloSlider(final Iterator<ObservedSlo> multi, final int limit,
      final BiFunction<ObservedSloFilter, ObservedSloCursor, Iterator<ObservedSlo>> gateway,
      final ObservedSloFilter filter, final ObservedSloCursor cursor) {
    super(multi, limit);
    this.gateway = gateway;
    this.filter = filter;
    this.cursor = cursor;
  }

  /**
   * @autogenerated SlideGenerator
   * @param observedSlos
   * @param limit
   * @return
   */
  @Override
  public Iterator<ObservedSlo> next(List<ObservedSlo> observedSlos, int limit) {
    ObservedSlo last = observedSlos.get(observedSlos.size() - 1);
    ObservedSloCursor cr = this.cursor.withSinceUid(last.getUid()).withLimit(limit);
    return gateway.apply(this.filter, cr);
  }
}
